// Linux developer check of real editor loop reconciliation against the CTest fake ALSA.
// Link with the editor objects generated by verify_walker_factory_scene.py.
// Factory-completion fixtures through the real editor scene builder.
// Explicit GPU/window boundary stubs: this checks CPU geometry/material submission,
// not Vulkan pixels or a replay of the uploaded simulations.
// Executes the real editor CPU scene builder with only the GPU/window boundary stubbed.
// This is an explicit developer probe, not Vulkan playback validation.
#include "editor_app.hpp"
#include <imgui.h>
#include "thandor/simulation_lab_runtime.hpp"
#include "thandor/simulation_lab_environment.hpp"
#include "thandor/simulation_lab_catalog.hpp"
using namespace thandor;
#include <fstream>
#include <dlfcn.h>
#include <thread>
#include <chrono>
#include <iostream>
namespace editor {
static std::vector<bool> texture_has_alpha;
static std::vector<thandor::RgbaImage> texture_images;
VulkanContext::VulkanContext(GLFWwindow* w):window_(w){max_image_array_layers_=4096;}
VulkanContext::~VulkanContext()=default;
void VulkanContext::wait_idle()const{}
TerrainRenderer::TerrainRenderer(VulkanContext& c):context_(c){}
TerrainRenderer::~TerrainRenderer()=default;
void TerrainRenderer::update_mesh(const thandor::FieldGrid&,const thandor::TerrainLighting&,const thandor::TerrainTextureLayout*,const thandor::TerrainSurfaceTextureLayout*,bool,uint32_t,uint32_t){}
void TerrainRenderer::update_materials(std::span<const thandor::RgbaImage>){}
void TerrainRenderer::update_surface_materials(std::span<const thandor::RgbaImage>){}
void TerrainRenderer::update_objects(std::span<const ObjectVertex>,std::span<const uint32_t> i,std::span<const ObjectDrawRun>r,std::span<const ObjectVertex>,std::span<const uint32_t>,std::span<const thandor::RgbaImage>t){texture_images.assign(t.begin(),t.end());texture_has_alpha.clear();for(const auto&im:t){bool visible=false;for(size_t a=3;a<im.pixels.size();a+=4)visible|=im.pixels[a]>=7;texture_has_alpha.push_back(visible);}
object_index_count_=i.size();object_draw_runs_.assign(r.begin(),r.end());object_texture_layer_count_=t.size();}
struct EditorUiValidation {
 static void run(EditorApp& app){
  void* library=dlopen("libasound.so.2",RTLD_NOW);
  const auto mode=reinterpret_cast<void(*)(int)>(dlsym(library,"test_alsa_mode"));
  const auto opens=reinterpret_cast<int(*)()>(dlsym(library,"test_alsa_opens"));
  if(!mode||!opens)throw std::runtime_error("Run with LD_LIBRARY_PATH pointing to the CTest audio_test_backend");
  // Stock radius 50000 Q12 must remain audible near a visible map focus,
  // even at overview zoom. Original listener mode remains available.
  auto lab=std::make_shared<SimulationLabExperiment>();
  SimulationLabConfig config;config.run_count=1;config.duration_ticks=120;
  std::array<uint32_t,AiKnowledgeData::kParameterCount> ki{};
  lab->reset(config,ki,{});app.simulation_lab_snapshot_=lab;
  app.camera_.target={20,-20,1};app.camera_.distance=100;
  app.simulation_sound_at_map_focus_=false;
  auto camera=app.spatial_audio_listener();
  if(spatial_sound_gains_q15(camera,{20,-20,1},32768,50000).audible())throw std::runtime_error("original camera listener fixture should be out of range");
  app.simulation_sound_at_map_focus_=true;
  auto focus=app.spatial_audio_listener();
  if(!spatial_sound_gains_q15(focus,{20,-20,1},32768,50000).audible()||focus.position[2]!=1)
   throw std::runtime_error("map-focus audio was muted by overview zoom");
  app.stop_all_runtime_looping_sounds();app.looping_sound_start_failures_.clear();
  app.sound_playback_enabled_=true;app.sound_effects_gain_q15_=0x8000;
  const int initial_opens=opens();mode(1);
  std::unordered_map<uint32_t,EditorApp::RuntimeSpatialSoundRequest> wanted;
  const auto listener=app.spatial_audio_listener();
  wanted[27].world_position={listener.position[0],listener.position[1],listener.position[2]};wanted[27].gain_q15=0x8000;wanted[27].maximum_distance_q12=65536;
  for(int i=0;i<100;++i)app.reconcile_runtime_looping_sounds(wanted);
  if(opens()!=initial_opens+1||!app.active_looping_sounds_.empty()||app.looping_sound_start_failures_.contains(27))
   throw std::runtime_error("Transient loop failure: opens="+std::to_string(opens())+" initial="+std::to_string(initial_opens)+" cached="+std::to_string(app.looping_sound_start_failures_.contains(27))+" status="+app.sound_playback_status_);
  mode(0);std::this_thread::sleep_for(std::chrono::milliseconds(5100));
  app.reconcile_runtime_looping_sounds(wanted);
  if(opens()!=initial_opens+2||!app.active_looping_sounds_.contains(27)||!app.active_looping_sounds_.at(27).voice->active())
   throw std::runtime_error("Editor loop did not recover automatically: "+app.sound_playback_status_);
  const auto before=audio_playback_diagnostics();
  app.play_runtime_spatial_sound(9,app.camera_.target,32768,50000);
  if(audio_playback_diagnostics().one_shots_queued!=before.one_shots_queued+1)
   throw std::runtime_error("visible map-focus one-shot did not reach the host");
  app.reconcile_runtime_looping_sounds({});
  if(!app.active_looping_sounds_.empty())throw std::runtime_error("Editor did not retire unwanted loop");
  std::cout<<"AUDIO_EDITOR_RECOVERY PASS actual_reconcile=1 blocked_calls=100 automatic_retry=1 map_focus_zoom=1 one_shot_queued=1 GPU_boundary_stubbed=1\n";
 }
};
}
int main(int argc,char**argv)try{
 if(argc!=2)throw std::runtime_error("Usage: audio_editor_recovery_probe GAME_ROOT (CTest fake ALSA on LD_LIBRARY_PATH)");
 void* library=dlopen("libasound.so.2",RTLD_NOW);
 if(!library||!dlsym(library,"test_alsa_mode"))throw std::runtime_error("CTest fake ALSA required");
 editor::VulkanContext vk(nullptr);editor::EditorApp app(nullptr,vk,argv[1]);editor::EditorUiValidation::run(app);
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
